    21→// Session represents a Claude Code session with its checkpoints.
    22→// A session is created when a user runs `claude` and tracks all changes
    23→// made during that interaction.
    24→type Session struct {
    25→	// ID is the unique session identifier (e.g., "2025-12-01-8f76b0e8-b8f1-4a87-9186-848bdd83d62e")
    26→	ID string
    27→
    28→	// Description is a human-readable summary of the session
    29→	// (typically the first prompt or derived from commit messages)
    30→	Description string
    31→
    32→	// Strategy is the name of the strategy that created this session
    33→	Strategy string
    34→
    35→	// StartTime is when the session was started
    36→	StartTime time.Time
    37→
    38→	// Checkpoints is the list of save points within this session
    39→	Checkpoints []Checkpoint
    40→}
    41→
    42→// Checkpoint represents a save point within a session.
    43→// Checkpoints can be either session-level (on Stop) or task-level (on subagent completion).
    44→type Checkpoint struct {
    45→	// CheckpointID is the stable 12-hex-char identifier for this checkpoint.
    46→	// Used to look up metadata at <id[:2]>/<id[2:]>/ on entire/sessions branch.
    47→	CheckpointID id.CheckpointID
    48→
    49→	// Message is the commit message or checkpoint description
    50→	Message string
    51→
    52→	// Timestamp is when this checkpoint was created
    53→	Timestamp time.Time
    54→
    55→	// IsTaskCheckpoint indicates if this is a task checkpoint (vs a session checkpoint)
    56→	IsTaskCheckpoint bool
    57→
    58→	// ToolUseID is the tool use ID for task checkpoints (empty for session checkpoints)
    59→	ToolUseID string
    60→}
    61→
