    87→// ListSessions returns all sessions from the entire/sessions branch,
    88→// plus any additional sessions from strategies implementing SessionSource.
    89→// It automatically discovers all registered strategies and merges their sessions.
    90→func ListSessions() ([]Session, error) {
    91→	repo, err := OpenRepository()
    92→	if err != nil {
    93→		return nil, fmt.Errorf("failed to open git repository: %w", err)
    94→	}
    95→
    96→	// Get checkpoints from the entire/sessions branch
    97→	checkpoints, err := ListCheckpoints()
    98→	if err != nil {
    99→		return nil, fmt.Errorf("failed to list checkpoints: %w", err)
   100→	}
   101→
   102→	// Group checkpoints by session ID
   103→	// For multi-session checkpoints, expand SessionIDs array so each session gets the checkpoint
   104→	sessionMap := make(map[string]*Session)
   105→	for _, cp := range checkpoints {
   106→		// Determine which session IDs this checkpoint belongs to
   107→		// Multi-session checkpoints have SessionIDs populated; single-session use SessionID
   108→		sessionIDs := cp.SessionIDs
   109→		if len(sessionIDs) == 0 {
   110→			sessionIDs = []string{cp.SessionID}
   111→		}
   112→
   113→		for _, sessionID := range sessionIDs {
   114→			if sessionID == "" {
   115→				continue
   116→			}
   117→
   118→			if existing, ok := sessionMap[sessionID]; ok {
   119→				existing.Checkpoints = append(existing.Checkpoints, Checkpoint{
   120→					CheckpointID:     cp.CheckpointID,
   121→					Message:          "Checkpoint: " + cp.CheckpointID.String(),
   122→					Timestamp:        cp.CreatedAt,
   123→					IsTaskCheckpoint: cp.IsTask,
   124→					ToolUseID:        cp.ToolUseID,
   125→				})
   126→			} else {
   127→				// Get description from the checkpoint tree
   128→				description := getDescriptionForCheckpoint(repo, cp.CheckpointID)
   129→
   130→				sessionMap[sessionID] = &Session{
   131→					ID:          sessionID,
   132→					Description: description,
   133→					Strategy:    "", // Will be set from metadata if available
   134→					StartTime:   cp.CreatedAt,
   135→					Checkpoints: []Checkpoint{{
   136→						CheckpointID:     cp.CheckpointID,
   137→						Message:          "Checkpoint: " + cp.CheckpointID.String(),
   138→						Timestamp:        cp.CreatedAt,
   139→						IsTaskCheckpoint: cp.IsTask,
   140→						ToolUseID:        cp.ToolUseID,
   141→					}},
   142→				}
   143→			}
   144→		}
   145→	}
   146→
   147→	// Check all registered strategies for additional sessions
   148→	for _, name := range List() {
   149→		strat, stratErr := Get(name)
   150→		if stratErr != nil {
   151→			continue
   152→		}
   153→		source, ok := strat.(SessionSource)
   154→		if !ok {
   155→			continue
   156→		}
   157→		additionalSessions, addErr := source.GetAdditionalSessions()
   158→		if addErr != nil {
   159→			continue // Skip strategies that fail to provide additional sessions
   160→		}
   161→		for _, addSession := range additionalSessions {
   162→			if addSession == nil {
   163→				continue
   164→			}
   165→			if existing, ok := sessionMap[addSession.ID]; ok {
   166→				// Merge checkpoints - deduplicate by CheckpointID
   167→				existingCPIDs := make(map[string]bool)
   168→				for _, cp := range existing.Checkpoints {
   169→					existingCPIDs[cp.CheckpointID.String()] = true
   170→				}
   171→				for _, cp := range addSession.Checkpoints {
   172→					if !existingCPIDs[cp.CheckpointID.String()] {
   173→						existing.Checkpoints = append(existing.Checkpoints, cp)
   174→					}
   175→				}
   176→				// Update start time if additional session is older
   177→				if addSession.StartTime.Before(existing.StartTime) {
   178→					existing.StartTime = addSession.StartTime
   179→				}
   180→				// Use description from additional source if existing is empty
   181→				if existing.Description == "" || existing.Description == NoDescription {
   182→					existing.Description = addSession.Description
   183→				}
   184→			} else {
   185→				// New session from additional source
   186→				sessionMap[addSession.ID] = addSession
   187→			}
   188→		}
   189→	}
   190→
   191→	// Convert map to slice
   192→	sessions := make([]Session, 0, len(sessionMap))
   193→	for _, session := range sessionMap {
   194→		// Sort checkpoints within each session by timestamp (most recent first)
   195→		sort.Slice(session.Checkpoints, func(i, j int) bool {
   196→			return session.Checkpoints[i].Timestamp.After(session.Checkpoints[j].Timestamp)
   197→		})
   198→		sessions = append(sessions, *session)
   199→	}
   200→
   201→	// Sort sessions by start time (most recent first)
   202→	sort.Slice(sessions, func(i, j int) bool {
   203→		return sessions[i].StartTime.After(sessions[j].StartTime)
   204→	})
   205→
   206→	return sessions, nil
   207→}
