   209→// GetSession finds a session by ID (supports prefix matching).
   210→// Returns ErrNoSession if no matching session is found.
   211→func GetSession(sessionID string) (*Session, error) {
   212→	sessions, err := ListSessions()
   213→	if err != nil {
   214→		return nil, err
   215→	}
   216→	return findSessionByID(sessions, sessionID)
   217→}
