   219→// getDescriptionForCheckpoint reads the description for a checkpoint from the entire/sessions branch.
   220→// It reads from the latest session subdirectory in the new storage format.
   221→func getDescriptionForCheckpoint(repo *git.Repository, checkpointID id.CheckpointID) string {
   222→	tree, err := GetMetadataBranchTree(repo)
   223→	if err != nil {
   224→		return NoDescription
   225→	}
   226→
   227→	// Get the checkpoint tree
   228→	checkpointTree, err := tree.Tree(checkpointID.Path())
   229→	if err != nil {
   230→		return NoDescription
   231→	}
   232→
   233→	// Read root metadata.json to get session count and sessions map
   234→	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
   235→	if err != nil {
   236→		return NoDescription
   237→	}
   238→
   239→	content, err := metadataFile.Contents()
   240→	if err != nil {
   241→		return NoDescription
   242→	}
   243→
   244→	var summary checkpoint.CheckpointSummary
   245→	if err := json.Unmarshal([]byte(content), &summary); err != nil {
   246→		return NoDescription
   247→	}
   248→
   249→	// Find the first session's prompt/context path
   250→	// Try to use the latest session for description (1-based indexing)
   251→	sessionDir := "1"
   252→	if len(summary.Sessions) > 0 {
   253→		sessionDir = strconv.Itoa(len(summary.Sessions)) // Use latest session
   254→	}
   255→
   256→	sessionTree, err := checkpointTree.Tree(sessionDir)
   257→	if err != nil {
   258→		return NoDescription
   259→	}
   260→
   261→	return getSessionDescriptionFromTree(sessionTree, "")
   262→}
   263→
   264→// findSessionByID finds a session by exact ID or prefix match.
   265→func findSessionByID(sessions []Session, sessionID string) (*Session, error) {
   266→	for _, session := range sessions {
   267→		if session.ID == sessionID || strings.HasPrefix(session.ID, sessionID) {
   268→			return &session, nil
   269→		}
   270→	}
   271→	return nil, ErrNoSession
   272→}
