   220→// readLatestSessionMetadata reads the session-specific metadata from the latest session subdirectory.
   221→// This is where session-specific fields like Summary are stored.
   222→func readLatestSessionMetadata(t *testing.T, repo *git.Repository, checkpointID id.CheckpointID) CommittedMetadata {
   223→	t.Helper()
   224→
   225→	ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
   226→	if err != nil {
   227→		t.Fatalf("failed to get metadata branch reference: %v", err)
   228→	}
   229→
   230→	commit, err := repo.CommitObject(ref.Hash())
   231→	if err != nil {
   232→		t.Fatalf("failed to get commit object: %v", err)
   233→	}
   234→
   235→	tree, err := commit.Tree()
   236→	if err != nil {
   237→		t.Fatalf("failed to get tree: %v", err)
   238→	}
   239→
   240→	checkpointTree, err := tree.Tree(checkpointID.Path())
   241→	if err != nil {
   242→		t.Fatalf("failed to get checkpoint tree: %v", err)
   243→	}
   244→
   245→	// Read root metadata.json to get session count
   246→	rootFile, err := checkpointTree.File(paths.MetadataFileName)
   247→	if err != nil {
   248→		t.Fatalf("failed to find root metadata.json: %v", err)
   249→	}
   250→
   251→	rootContent, err := rootFile.Contents()
   252→	if err != nil {
   253→		t.Fatalf("failed to read root metadata.json: %v", err)
   254→	}
   255→
   256→	var summary CheckpointSummary
   257→	if err := json.Unmarshal([]byte(rootContent), &summary); err != nil {
   258→		t.Fatalf("failed to parse root metadata.json: %v", err)
   259→	}
   260→
   261→	// Read session-level metadata from latest session subdirectory (1-based indexing)
   262→	latestIndex := len(summary.Sessions)
   263→	sessionDir := strconv.Itoa(latestIndex)
   264→	sessionTree, err := checkpointTree.Tree(sessionDir)
   265→	if err != nil {
   266→		t.Fatalf("failed to get session tree at %s: %v", sessionDir, err)
   267→	}
   268→
   269→	sessionFile, err := sessionTree.File(paths.MetadataFileName)
   270→	if err != nil {
   271→		t.Fatalf("failed to find session metadata.json: %v", err)
   272→	}
   273→
   274→	content, err := sessionFile.Contents()
   275→	if err != nil {
   276→		t.Fatalf("failed to read session metadata.json: %v", err)
   277→	}
   278→
   279→	var metadata CommittedMetadata
   280→	if err := json.Unmarshal([]byte(content), &metadata); err != nil {
   281→		t.Fatalf("failed to parse session metadata.json: %v", err)
   282→	}
   283→
   284→	return metadata
   285→}
