   548→// TestWriteCommitted_BranchField verifies that the Branch field is correctly
   549→// captured in metadata.json when on a branch, and is empty when in detached HEAD.
   550→func TestWriteCommitted_BranchField(t *testing.T) {
   551→	t.Run("on branch", func(t *testing.T) {
   552→		repo, commitHash := setupBranchTestRepo(t)
   553→
   554→		// Create a feature branch and switch to it
   555→		branchName := "feature/test-branch"
   556→		branchRef := plumbing.NewBranchReferenceName(branchName)
   557→		ref := plumbing.NewHashReference(branchRef, commitHash)
   558→		if err := repo.Storer.SetReference(ref); err != nil {
   559→			t.Fatalf("failed to create branch: %v", err)
   560→		}
   561→
   562→		worktree, err := repo.Worktree()
   563→		if err != nil {
   564→			t.Fatalf("failed to get worktree: %v", err)
   565→		}
   566→		if err := worktree.Checkout(&git.CheckoutOptions{Branch: branchRef}); err != nil {
   567→			t.Fatalf("failed to checkout branch: %v", err)
   568→		}
   569→
   570→		// Get current branch name
   571→		var currentBranch string
   572→		head, err := repo.Head()
   573→		if err == nil && head.Name().IsBranch() {
   574→			currentBranch = head.Name().Short()
   575→		}
   576→
   577→		// Write a committed checkpoint with branch information
   578→		checkpointID := id.MustCheckpointID("a1b2c3d4e5f6")
   579→		store := NewGitStore(repo)
   580→		err = store.WriteCommitted(context.Background(), WriteCommittedOptions{
   581→			CheckpointID: checkpointID,
   582→			SessionID:    "test-session-123",
   583→			Strategy:     "manual-commit",
   584→			Branch:       currentBranch,
   585→			Transcript:   []byte("test transcript content"),
   586→			AuthorName:   "Test Author",
   587→			AuthorEmail:  "test@example.com",
   588→		})
   589→		if err != nil {
   590→			t.Fatalf("WriteCommitted() error = %v", err)
   591→		}
   592→
   593→		verifyBranchInMetadata(t, repo, checkpointID, branchName, false)
   594→	})
   595→
   596→	t.Run("detached HEAD", func(t *testing.T) {
   597→		repo, commitHash := setupBranchTestRepo(t)
   598→
   599→		// Checkout the commit directly (detached HEAD)
   600→		worktree, err := repo.Worktree()
   601→		if err != nil {
   602→			t.Fatalf("failed to get worktree: %v", err)
   603→		}
   604→		if err := worktree.Checkout(&git.CheckoutOptions{Hash: commitHash}); err != nil {
   605→			t.Fatalf("failed to checkout commit: %v", err)
   606→		}
   607→
   608→		// Verify we're in detached HEAD
   609→		head, err := repo.Head()
   610→		if err != nil {
   611→			t.Fatalf("failed to get HEAD: %v", err)
   612→		}
   613→		if head.Name().IsBranch() {
   614→			t.Fatalf("expected detached HEAD, but on branch %s", head.Name().Short())
   615→		}
   616→
   617→		// Write a committed checkpoint (branch should be empty in detached HEAD)
   618→		checkpointID := id.MustCheckpointID("b2c3d4e5f6a7")
   619→		store := NewGitStore(repo)
   620→		err = store.WriteCommitted(context.Background(), WriteCommittedOptions{
   621→			CheckpointID: checkpointID,
   622→			SessionID:    "test-session-456",
   623→			Strategy:     "manual-commit",
   624→			Branch:       "", // Empty when in detached HEAD
   625→			Transcript:   []byte("test transcript content"),
   626→			AuthorName:   "Test Author",
   627→			AuthorEmail:  "test@example.com",
   628→		})
   629→		if err != nil {
   630→			t.Fatalf("WriteCommitted() error = %v", err)
   631→		}
   632→
   633→		verifyBranchInMetadata(t, repo, checkpointID, "", true)
   634→	})
   635→}
