  1226→
  1227→// getCheckpointTree returns the tree for a checkpoint on the sessions branch.
  1228→func getCheckpointTree(t *testing.T, repo *git.Repository, checkpointID id.CheckpointID) *object.Tree {
  1229→	t.Helper()
  1230→
  1231→	ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
  1232→	if err != nil {
  1233→		t.Fatalf("failed to get metadata branch reference: %v", err)
  1234→	}
  1235→
  1236→	commit, err := repo.CommitObject(ref.Hash())
  1237→	if err != nil {
  1238→		t.Fatalf("failed to get commit object: %v", err)
  1239→	}
  1240→
  1241→	tree, err := commit.Tree()
  1242→	if err != nil {
  1243→		t.Fatalf("failed to get tree: %v", err)
  1244→	}
  1245→
  1246→	checkpointTree, err := tree.Tree(checkpointID.Path())
  1247→	if err != nil {
  1248→		t.Fatalf("failed to get checkpoint tree at %s: %v", checkpointID.Path(), err)
  1249→	}
  1250→
  1251→	return checkpointTree
  1252→}
