  1254→// readMetadataFromTree reads metadata.json from a tree and unmarshals to given type.
  1255→func readMetadataFromTree[T any](t *testing.T, tree *object.Tree, desc string) *T {
  1256→	t.Helper()
  1257→
  1258→	file, err := tree.File(paths.MetadataFileName)
  1259→	if err != nil {
  1260→		t.Fatalf("failed to find %s metadata.json: %v", desc, err)
  1261→	}
  1262→
  1263→	content, err := file.Contents()
  1264→	if err != nil {
  1265→		t.Fatalf("failed to read %s metadata.json: %v", desc, err)
  1266→	}
  1267→
  1268→	var result T
  1269→	if err := json.Unmarshal([]byte(content), &result); err != nil {
  1270→		t.Fatalf("failed to parse %s metadata.json: %v", desc, err)
  1271→	}
  1272→
  1273→	return &result
  1274→}
  1275→
  1276→// readRootMetadata reads the CheckpointSummary from root metadata.json.
  1277→func readRootMetadata(t *testing.T, tree *object.Tree) *CheckpointSummary {
  1278→	return readMetadataFromTree[CheckpointSummary](t, tree, "root")
  1279→}
