  1281→// readSessionMetadataFromTree reads CommittedMetadata from a session subdirectory tree.
  1282→func readSessionMetadataFromTree(t *testing.T, sessionTree *object.Tree) *CommittedMetadata {
  1283→	return readMetadataFromTree[CommittedMetadata](t, sessionTree, "session")
  1284→}
