   332→// TestListSessionsMultiSessionCheckpoint verifies that archived sessions in multi-session
   333→// checkpoints are listed correctly. When multiple sessions are condensed to the same
   334→// checkpoint, they are stored as:
   335→//   - Root level: latest session (SessionID)
   336→//   - 1/, 2/, etc.: archived sessions (in SessionIDs array)
   337→//
   338→// ListSessions should return ALL sessions from SessionIDs, not just SessionID.
   339→func TestListSessionsMultiSessionCheckpoint(t *testing.T) {
   340→	tmpDir := t.TempDir()
   341→	resolved, err := filepath.EvalSymlinks(tmpDir)
   342→	if err != nil {
   343→		t.Fatalf("filepath.EvalSymlinks() failed: %v", err)
   344→	}
