   346→
   347→	initTestRepo(t, tmpDir)
   348→	t.Chdir(tmpDir)
   349→
   350→	repo, err := OpenRepository()
   351→	if err != nil {
   352→		t.Fatalf("OpenRepository() failed: %v", err)
   353→	}
   354→
   355→	// Create a multi-session checkpoint with 2 sessions:
   356→	// - session-A: archived in 1/ subfolder
   357→	// - session-B: latest at root level
   358→	sessionA := "2025-01-14-session-A"
   359→	sessionB := "2025-01-15-session-B"
   360→	checkpointID := id.MustCheckpointID("ab12cd34ef56")
   361→
   362→	createTestMultiSessionCheckpoint(t, repo, checkpointID, sessionB, []string{sessionA, sessionB})
   363→
   364→	sessions, err := ListSessions()
   365→	if err != nil {
   366→		t.Fatalf("ListSessions() error = %v, want nil", err)
   367→	}
   368→
   369→	// Should return 2 sessions - one for each session ID in the checkpoint
   370→	if len(sessions) != 2 {
   371→		t.Fatalf("ListSessions() returned %d sessions, want 2 (both session-A and session-B)", len(sessions))
   372→	}
   373→
   374→	// Verify both sessions are present
   375→	sessionIDs := make(map[string]bool)
   376→	for _, sess := range sessions {
   377→		sessionIDs[sess.ID] = true
   378→	}
   379→
   380→	if !sessionIDs[sessionA] {
   381→		t.Errorf("ListSessions() missing archived session %q", sessionA)
   382→	}
   383→	if !sessionIDs[sessionB] {
   384→		t.Errorf("ListSessions() missing latest session %q", sessionB)
   385→	}
   386→
   387→	// Both sessions should have the same checkpoint
   388→	for _, sess := range sessions {
   389→		if len(sess.Checkpoints) != 1 {
   390→			t.Errorf("Session %q has %d checkpoints, want 1", sess.ID, len(sess.Checkpoints))
   391→		}
   392→		if len(sess.Checkpoints) > 0 && sess.Checkpoints[0].CheckpointID != checkpointID {
   393→			t.Errorf("Session %q checkpoint ID = %q, want %q", sess.ID, sess.Checkpoints[0].CheckpointID, checkpointID)
   394→		}
   395→	}
   396→}
