   398→// Helper function to create a test metadata branch with a multi-session checkpoint
   399→func createTestMultiSessionCheckpoint(t *testing.T, repo *git.Repository, checkpointID id.CheckpointID, primarySessionID string, allSessionIDs []string) {
   400→	t.Helper()
   401→
   402→	entries := make(map[string]object.TreeEntry)
   403→	checkpointPath := checkpointID.Path()
   404→
   405→	// Create session-level metadata for each session (1-based indexing)
   406→	var sessionFilePaths []checkpoint.SessionFilePaths
   407→	for i, sessionID := range allSessionIDs {
   408→		sessionDir := strconv.Itoa(i + 1) // 1-based: 1, 2, 3, ...
   409→		sessionMetadata := checkpoint.CommittedMetadata{
   410→			CheckpointID: checkpointID,
   411→			SessionID:    sessionID,
   412→			CreatedAt:    time.Now(),
   413→		}
   414→		sessionMetadataJSON, err := json.Marshal(sessionMetadata)
   415→		if err != nil {
   416→			t.Fatalf("failed to marshal session metadata: %v", err)
   417→		}
   418→		sessionMetadataBlobHash, err := checkpoint.CreateBlobFromContent(repo, sessionMetadataJSON)
   419→		if err != nil {
   420→			t.Fatalf("failed to create session metadata blob: %v", err)
   421→		}
   422→		sessionMetadataPath := checkpointPath + "/" + sessionDir + "/" + paths.MetadataFileName
   423→		entries[sessionMetadataPath] = object.TreeEntry{
   424→			Name: sessionMetadataPath,
   425→			Mode: filemode.Regular,
   426→			Hash: sessionMetadataBlobHash,
   427→		}
   428→		// Use absolute paths with leading "/" as per new format
   429→		sessionFilePaths = append(sessionFilePaths, checkpoint.SessionFilePaths{
   430→			Metadata: "/" + checkpointPath + "/" + sessionDir + "/" + paths.MetadataFileName,
   431→		})
   432→	}
   433→
   434→	// Create root CheckpointSummary with Sessions array (using absolute paths)
   435→	summary := checkpoint.CheckpointSummary{
   436→		CheckpointID: checkpointID,
   437→		Sessions:     sessionFilePaths,
   438→	}
   439→	summaryJSON, err := json.Marshal(summary)
   440→	if err != nil {
   441→		t.Fatalf("failed to marshal summary: %v", err)
   442→	}
   443→	summaryBlobHash, err := checkpoint.CreateBlobFromContent(repo, summaryJSON)
   444→	if err != nil {
   445→		t.Fatalf("failed to create summary blob: %v", err)
   446→	}
   447→	entries[checkpointPath+"/"+paths.MetadataFileName] = object.TreeEntry{
   448→		Name: checkpointPath + "/" + paths.MetadataFileName,
   449→		Mode: filemode.Regular,
   450→		Hash: summaryBlobHash,
   451→	}
   452→
   453→	// Build tree
   454→	treeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
   455→	if err != nil {
   456→		t.Fatalf("failed to build tree: %v", err)
   457→	}
   458→
   459→	// Create orphan commit
   460→	now := time.Now()
   461→	sig := object.Signature{
   462→		Name:  "Test",
   463→		Email: "test@test.com",
   464→		When:  now,
   465→	}
   466→	commit := &object.Commit{
   467→		TreeHash:  treeHash,
   468→		Author:    sig,
   469→		Committer: sig,
   470→		Message:   "Multi-session checkpoint\n\n" + trailers.SessionTrailerKey + ": " + primarySessionID,
   471→	}
   472→
   473→	commitObj := repo.Storer.NewEncodedObject()
   474→	if err := commit.Encode(commitObj); err != nil {
   475→		t.Fatalf("failed to encode commit: %v", err)
   476→	}
   477→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
   478→	if err != nil {
   479→		t.Fatalf("failed to store commit: %v", err)
   480→	}
   481→
   482→	// Create branch reference
   483→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   484→	ref := plumbing.NewHashReference(refName, commitHash)
   485→	if err := repo.Storer.SetReference(ref); err != nil {
   486→		t.Fatalf("failed to create branch: %v", err)
   487→	}
   488→}
