   558→	summaryBlobHash, err := checkpoint.CreateBlobFromContent(repo, summaryJSON)
   559→	if err != nil {
   560→		t.Fatalf("failed to create summary blob: %v", err)
   561→	}
   562→	rootMetadataPath := checkpointPath + "/" + paths.MetadataFileName
   563→	entries[rootMetadataPath] = object.TreeEntry{
   564→		Name: rootMetadataPath,
   565→		Mode: filemode.Regular,
   566→		Hash: summaryBlobHash,
   567→	}
   568→
   569→	// Build tree
   570→	treeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
   571→	if err != nil {
   572→		t.Fatalf("failed to build tree: %v", err)
   573→	}
   574→
   575→	// Create orphan commit
   576→	now := time.Now()
