   489→func TestShadowStrategy_CanRewind_DirtyRepo(t *testing.T) {
   490→	// For shadow, CanRewind always returns true because rewinding
   491→	// replaces local changes with checkpoint contents - that's the expected behavior.
   492→	// Users rewind to undo Claude's changes, which are uncommitted by definition.
   493→	// However, it now returns a warning message with diff stats.
   494→	dir := t.TempDir()
   495→	repo, err := git.PlainInit(dir, false)
   496→	if err != nil {
   497→		t.Fatalf("failed to init git repo: %v", err)
   498→	}
   499→
   500→	// Create initial commit
   501→	worktree, err := repo.Worktree()
   502→	if err != nil {
   503→		t.Fatalf("failed to get worktree: %v", err)
   504→	}
   505→	testFile := filepath.Join(dir, "test.txt")
   506→	if err := os.WriteFile(testFile, []byte("line1\nline2\nline3\n"), 0o644); err != nil {
   507→		t.Fatalf("failed to write test file: %v", err)
   508→	}
   509→	if _, err := worktree.Add("test.txt"); err != nil {
   510→		t.Fatalf("failed to add file: %v", err)
   511→	}
   512→	_, err = worktree.Commit("Initial commit", &git.CommitOptions{
   513→		Author: &object.Signature{Name: "Test", Email: "test@test.com"},
   514→	})
   515→	if err != nil {
   516→		t.Fatalf("failed to commit: %v", err)
   517→	}
   518→
   519→	// Make the repo dirty by modifying the file
   520→	if err := os.WriteFile(testFile, []byte("line1\nmodified line2\nline3\nnew line4\n"), 0o644); err != nil {
   521→		t.Fatalf("failed to modify test file: %v", err)
   522→	}
   523→
   524→	t.Chdir(dir)
   525→
   526→	s := NewManualCommitStrategy()
   527→	can, reason, err := s.CanRewind()
   528→	if err != nil {
   529→		t.Errorf("CanRewind() error = %v", err)
   530→	}
   531→	if !can {
   532→		t.Error("CanRewind() = false, want true (shadow always allows rewind)")
   533→	}
