  1011→		CommitMessage:  "Checkpoint 1",
  1012→		AuthorName:     "Test",
  1013→		AuthorEmail:    "test@test.com",
  1014→	})
  1015→	if err != nil {
  1016→		t.Fatalf("SaveChanges() error = %v", err)
  1017→	}
  1018→
  1019→	// Now simulate a second checkpoint where ONLY existing1.txt is modified
  1020→	// (but NOT existing2.txt or existing3.txt)
  1021→	modifiedContent := []byte("MODIFIED content of existing1.txt")
  1022→	if err := os.WriteFile(filepath.Join(dir, "existing1.txt"), modifiedContent, 0o644); err != nil {
  1023→		t.Fatalf("failed to modify existing1.txt: %v", err)
  1024→	}
  1025→
  1026→	// Second checkpoint using SaveChanges - only modified file should be tracked
  1027→	err = s.SaveChanges(SaveContext{
  1028→		SessionID:      sessionID,
  1029→		ModifiedFiles:  []string{"existing1.txt"}, // Only this file was modified
  1030→		NewFiles:       []string{},
  1031→		DeletedFiles:   []string{},
  1032→		MetadataDir:    metadataDir,
