  1065→	// Verify the exact content
  1066→	filesTouchedMap := make(map[string]bool)
  1067→	for _, f := range result.FilesTouched {
  1068→		filesTouchedMap[f] = true
  1069→	}
  1070→
  1071→	// Check that ONLY the modified file is in files_touched
  1072→	for _, expected := range expectedFilesTouched {
