  1077→
  1078→	// Check that pre-existing unmodified files are NOT in files_touched
  1079→	unmodifiedFiles := []string{"existing2.txt", "existing3.txt"}
  1080→	for _, unmodified := range unmodifiedFiles {
  1081→		if filesTouchedMap[unmodified] {
