  1653→// TestCondenseSession_IncludesInitialAttribution verifies that when manual-commit
  1654→// condenses a session, it calculates InitialAttribution by comparing the shadow branch
  1655→// (agent work) to HEAD (what was committed).
  1656→func TestCondenseSession_IncludesInitialAttribution(t *testing.T) {
  1657→	dir := t.TempDir()
  1658→	repo, err := git.PlainInit(dir, false)
  1659→	if err != nil {
  1660→		t.Fatalf("failed to init repo: %v", err)
  1661→	}
  1662→
  1663→	// Create initial commit with a file
  1664→	worktree, err := repo.Worktree()
  1665→	if err != nil {
  1666→		t.Fatalf("failed to get worktree: %v", err)
  1667→	}
  1668→
  1669→	// Create a file with some content
  1670→	testFile := filepath.Join(dir, "test.go")
  1671→	originalContent := "package main\n\nfunc main() {\n\tprintln(\"hello\")\n}\n"
  1672→	if err := os.WriteFile(testFile, []byte(originalContent), 0o644); err != nil {
  1673→		t.Fatalf("failed to write file: %v", err)
  1674→	}
  1675→	if _, err := worktree.Add("test.go"); err != nil {
  1676→		t.Fatalf("failed to stage file: %v", err)
  1677→	}
  1678→
  1679→	_, err = worktree.Commit("Initial commit", &git.CommitOptions{
  1680→		Author: &object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
  1681→	})
  1682→	if err != nil {
  1683→		t.Fatalf("failed to commit: %v", err)
  1684→	}
  1685→
  1686→	t.Chdir(dir)
  1687→
  1688→	s := &ManualCommitStrategy{}
  1689→	sessionID := "2025-01-15-test-attribution"
  1690→
  1691→	// Create metadata directory with transcript
  1692→	metadataDir := ".entire/metadata/" + sessionID
  1693→	metadataDirAbs := filepath.Join(dir, metadataDir)
  1694→	if err := os.MkdirAll(metadataDirAbs, 0o755); err != nil {
  1695→		t.Fatalf("failed to create metadata dir: %v", err)
  1696→	}
  1697→
  1698→	transcript := `{"type":"human","message":{"content":"modify test.go"}}
  1699→{"type":"assistant","message":{"content":"I'll modify test.go"}}
  1700→`
  1701→	if err := os.WriteFile(filepath.Join(metadataDirAbs, paths.TranscriptFileName), []byte(transcript), 0o644); err != nil {
  1702→		t.Fatalf("failed to write transcript: %v", err)
  1703→	}
  1704→
  1705→	// Agent modifies the file (adds a new function)
  1706→	agentContent := "package main\n\nfunc main() {\n\tprintln(\"hello\")\n}\n\nfunc newFunc() {\n\tprintln(\"agent added this\")\n}\n"
  1707→	if err := os.WriteFile(testFile, []byte(agentContent), 0o644); err != nil {
  1708→		t.Fatalf("failed to write agent changes: %v", err)
  1709→	}
  1710→
  1711→	// First checkpoint - captures agent's work on shadow branch
  1712→	err = s.SaveChanges(SaveContext{
  1713→		SessionID:      sessionID,
  1714→		ModifiedFiles:  []string{"test.go"},
  1715→		NewFiles:       []string{},
  1716→		DeletedFiles:   []string{},
  1717→		MetadataDir:    metadataDir,
  1718→		MetadataDirAbs: metadataDirAbs,
  1719→		CommitMessage:  "Checkpoint 1",
  1720→		AuthorName:     "Test",
  1721→		AuthorEmail:    "test@test.com",
  1722→	})
  1723→	if err != nil {
  1724→		t.Fatalf("SaveChanges() error = %v", err)
  1725→	}
  1726→
  1727→	// Human edits the file (adds a comment)
  1728→	humanEditedContent := "package main\n\n// Human added this comment\nfunc main() {\n\tprintln(\"hello\")\n}\n\nfunc newFunc() {\n\tprintln(\"agent added this\")\n}\n"
  1729→	if err := os.WriteFile(testFile, []byte(humanEditedContent), 0o644); err != nil {
  1730→		t.Fatalf("failed to write human edits: %v", err)
  1731→	}
  1732→
  1733→	// Stage and commit the human-edited file (this is what the user does)
  1734→	if _, err := worktree.Add("test.go"); err != nil {
  1735→		t.Fatalf("failed to stage human edits: %v", err)
  1736→	}
  1737→	_, err = worktree.Commit("Add new function with human comment", &git.CommitOptions{
  1738→		Author: &object.Signature{Name: "Human", Email: "human@test.com", When: time.Now()},
  1739→	})
  1740→	if err != nil {
  1741→		t.Fatalf("failed to commit human edits: %v", err)
  1742→	}
  1743→
  1744→	// Load session state
  1745→	state, err := s.loadSessionState(sessionID)
  1746→	if err != nil {
  1747→		t.Fatalf("loadSessionState() error = %v", err)
  1748→	}
  1749→
  1750→	// Condense the session - this should calculate InitialAttribution
  1751→	checkpointID := id.MustCheckpointID("a1b2c3d4e5f6")
  1752→	result, err := s.CondenseSession(repo, checkpointID, state)
  1753→	if err != nil {
  1754→		t.Fatalf("CondenseSession() error = %v", err)
  1755→	}
  1756→
  1757→	// Verify CondenseResult
  1758→	if result.CheckpointID != checkpointID {
  1759→		t.Errorf("CheckpointID = %q, want %q", result.CheckpointID, checkpointID)
  1760→	}
  1761→
  1762→	// Read metadata from entire/sessions branch and verify InitialAttribution
  1763→	sessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
  1764→	if err != nil {
  1765→		t.Fatalf("failed to get sessions branch: %v", err)
  1766→	}
  1767→
  1768→	sessionsCommit, err := repo.CommitObject(sessionsRef.Hash())
  1769→	if err != nil {
  1770→		t.Fatalf("failed to get sessions commit: %v", err)
  1771→	}
  1772→
  1773→	tree, err := sessionsCommit.Tree()
  1774→	if err != nil {
  1775→		t.Fatalf("failed to get tree: %v", err)
  1776→	}
  1777→
  1778→	// InitialAttribution is stored in session-level metadata (1/metadata.json), not root (1-based indexing)
  1779→	sessionMetadataPath := checkpointID.Path() + "/1/" + paths.MetadataFileName
  1780→	metadataFile, err := tree.File(sessionMetadataPath)
  1781→	if err != nil {
  1782→		t.Fatalf("failed to find session metadata.json at %s: %v", sessionMetadataPath, err)
  1783→	}
  1784→
  1785→	content, err := metadataFile.Contents()
  1786→	if err != nil {
  1787→		t.Fatalf("failed to read metadata.json: %v", err)
  1788→	}
  1789→
  1790→	// Parse and verify InitialAttribution is present
  1791→	var metadata struct {
  1792→		InitialAttribution *struct {
  1793→			AgentLines      int     `json:"agent_lines"`
  1794→			HumanAdded      int     `json:"human_added"`
  1795→			HumanModified   int     `json:"human_modified"`
  1796→			HumanRemoved    int     `json:"human_removed"`
  1797→			TotalCommitted  int     `json:"total_committed"`
  1798→			AgentPercentage float64 `json:"agent_percentage"`
  1799→		} `json:"initial_attribution"`
  1800→	}
  1801→	if err := json.Unmarshal([]byte(content), &metadata); err != nil {
  1802→		t.Fatalf("failed to parse metadata.json: %v", err)
  1803→	}
  1804→
  1805→	if metadata.InitialAttribution == nil {
  1806→		t.Fatal("InitialAttribution should be present in session metadata.json for manual-commit")
  1807→	}
  1808→
  1809→	// Verify the attribution values are reasonable
  1810→	// Agent added new function, human added a comment line
  1811→	// The exact line counts depend on how the diff algorithm interprets the changes
  1812→	// (insertion vs modification), but we should have non-zero totals and reasonable percentages.
  1813→	if metadata.InitialAttribution.TotalCommitted == 0 {
  1814→		t.Error("TotalCommitted should be > 0")
  1815→	}
  1816→	if metadata.InitialAttribution.AgentLines == 0 {
  1817→		t.Error("AgentLines should be > 0 (agent wrote code)")
  1818→	}
  1819→
  1820→	// Human contribution should be captured in either HumanAdded or HumanModified
  1821→	// When inserting lines in the middle of existing code, the diff algorithm may
  1822→	// interpret it as a modification rather than a pure addition.
  1823→	humanContribution := metadata.InitialAttribution.HumanAdded + metadata.InitialAttribution.HumanModified
  1824→	if humanContribution == 0 {
  1825→		t.Error("Human contribution (HumanAdded + HumanModified) should be > 0")
  1826→	}
  1827→
  1828→	if metadata.InitialAttribution.AgentPercentage <= 0 || metadata.InitialAttribution.AgentPercentage > 100 {
  1829→		t.Errorf("AgentPercentage should be between 0-100, got %f", metadata.InitialAttribution.AgentPercentage)
  1830→	}
  1831→
  1832→	t.Logf("Attribution: agent=%d, human_added=%d, human_modified=%d, human_removed=%d, total=%d, percentage=%.1f%%",
  1833→		metadata.InitialAttribution.AgentLines,
  1834→		metadata.InitialAttribution.HumanAdded,
  1835→		metadata.InitialAttribution.HumanModified,
  1836→		metadata.InitialAttribution.HumanRemoved,
  1837→		metadata.InitialAttribution.TotalCommitted,
  1838→		metadata.InitialAttribution.AgentPercentage)
  1839→}
