  1913→// TestMultiCheckpoint_UserEditsBetweenCheckpoints tests that user edits made between
  1914→// agent checkpoints are correctly attributed to the user, not the agent.
  1915→//
  1916→// This tests two scenarios:
  1917→// 1. User edits a DIFFERENT file than agent - detected at checkpoint save time
  1918→// 2. User edits the SAME file as agent - detected at commit time (shadow → head diff)
  1919→//
  1920→//nolint:maintidx // Integration test with multiple steps is inherently complex
  1921→func TestMultiCheckpoint_UserEditsBetweenCheckpoints(t *testing.T) {
  1922→	dir := t.TempDir()
  1923→	repo, err := git.PlainInit(dir, false)
  1924→	if err != nil {
