  1934→	agentFile := filepath.Join(dir, "agent.go")
  1935→	userFile := filepath.Join(dir, "user.go")
  1936→	if err := os.WriteFile(agentFile, []byte("package main\n"), 0o644); err != nil {
  1937→		t.Fatalf("failed to write agent file: %v", err)
  1938→	}
  1939→	if err := os.WriteFile(userFile, []byte("package main\n"), 0o644); err != nil {
  1940→		t.Fatalf("failed to write user file: %v", err)
  1941→	}
  1942→	if _, err := worktree.Add("agent.go"); err != nil {
  1943→		t.Fatalf("failed to stage file: %v", err)
  1944→	}
  1945→	if _, err := worktree.Add("user.go"); err != nil {
  1946→		t.Fatalf("failed to stage file: %v", err)
  1947→	}
  1948→	_, err = worktree.Commit("Initial commit", &git.CommitOptions{
  1949→		Author: &object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
  1950→	})
  1951→	if err != nil {
  1952→		t.Fatalf("failed to commit: %v", err)
  1953→	}
  1954→
  1955→	t.Chdir(dir)
  1956→
  1957→	s := &ManualCommitStrategy{}
  1958→	sessionID := "2025-01-15-multi-checkpoint-test"
  1959→
  1960→	// Create metadata directory
  1961→	metadataDir := ".entire/metadata/" + sessionID
  1962→	metadataDirAbs := filepath.Join(dir, metadataDir)
  1963→	if err := os.MkdirAll(metadataDirAbs, 0o755); err != nil {
  1964→		t.Fatalf("failed to create metadata dir: %v", err)
  1965→	}
  1966→
  1967→	transcript := `{"type":"human","message":{"content":"add function"}}
  1968→{"type":"assistant","message":{"content":"adding function"}}
  1969→`
  1970→	if err := os.WriteFile(filepath.Join(metadataDirAbs, paths.TranscriptFileName), []byte(transcript), 0o644); err != nil {
  1971→		t.Fatalf("failed to write transcript: %v", err)
  1972→	}
  1973→
  1974→	// === PROMPT 1 START: Initialize session (simulates UserPromptSubmit) ===
  1975→	// This must happen BEFORE agent makes any changes
  1976→	if err := s.InitializeSession(sessionID, "Claude Code", ""); err != nil {
  1977→		t.Fatalf("InitializeSession() prompt 1 error = %v", err)
  1978→	}
  1979→
  1980→	// === CHECKPOINT 1: Agent modifies agent.go (adds 4 lines) ===
  1981→	checkpoint1Content := "package main\n\nfunc agentFunc1() {\n\tprintln(\"agent1\")\n}\n"
  1982→	if err := os.WriteFile(agentFile, []byte(checkpoint1Content), 0o644); err != nil {
  1983→		t.Fatalf("failed to write agent changes 1: %v", err)
  1984→	}
  1985→
  1986→	err = s.SaveChanges(SaveContext{
  1987→		SessionID:      sessionID,
  1988→		ModifiedFiles:  []string{"agent.go"},
  1989→		NewFiles:       []string{},
  1990→		DeletedFiles:   []string{},
  1991→		MetadataDir:    metadataDir,
