  2012→	}
  2013→
  2014→	// === USER EDITS A DIFFERENT FILE (user.go) BETWEEN CHECKPOINTS ===
  2015→	userEditContent := "package main\n\n// User added this function\nfunc userFunc() {\n\tprintln(\"user\")\n}\n"
  2016→	if err := os.WriteFile(userFile, []byte(userEditContent), 0o644); err != nil {
