  2031→
  2032→	err = s.SaveChanges(SaveContext{
  2033→		SessionID:      sessionID,
  2034→		ModifiedFiles:  []string{"agent.go"},
  2035→		NewFiles:       []string{},
  2036→		DeletedFiles:   []string{},
  2037→		MetadataDir:    metadataDir,
  2038→		MetadataDirAbs: metadataDirAbs,
  2039→		CommitMessage:  "Checkpoint 2",
  2040→		AuthorName:     "Test",
  2041→		AuthorEmail:    "test@test.com",
  2042→	})
  2043→	if err != nil {
  2044→		t.Fatalf("SaveChanges() checkpoint 2 error = %v", err)
  2045→	}
  2046→
  2047→	// Verify PromptAttribution was recorded for checkpoint 2
  2048→	state2, err := s.loadSessionState(sessionID)
  2049→	if err != nil {
  2050→		t.Fatalf("loadSessionState() after checkpoint 2 error = %v", err)
  2051→	}
  2052→	if len(state2.PromptAttributions) != 2 {
  2053→		t.Fatalf("expected 2 PromptAttributions after checkpoint 2, got %d", len(state2.PromptAttributions))
  2054→	}
  2055→
  2056→	t.Logf("Checkpoint 2 PromptAttribution: user_added=%d, user_removed=%d, agent_added=%d, agent_removed=%d",
  2057→		state2.PromptAttributions[1].UserLinesAdded,
  2058→		state2.PromptAttributions[1].UserLinesRemoved,
  2059→		state2.PromptAttributions[1].AgentLinesAdded,
  2060→		state2.PromptAttributions[1].AgentLinesRemoved)
  2061→
  2062→	// Second checkpoint should detect user's edits to user.go (different file than agent)
  2063→	// User added 5 lines to user.go
  2064→	if state2.PromptAttributions[1].UserLinesAdded == 0 {
  2065→		t.Error("checkpoint 2: expected user lines added > 0 because user edited user.go")
